-- ============================================================
-- Assessment 1: Shipments Table — Postgres (Supabase) Setup
-- ============================================================

CREATE TABLE IF NOT EXISTS public.shipments (
    ShipmentID        VARCHAR(20)    PRIMARY KEY,
    OrderID           VARCHAR(20)    NOT NULL,
    CarrierID         VARCHAR(10)    NOT NULL,
    SupplierID        VARCHAR(10)    NOT NULL,
    ShippingTierID    VARCHAR(10)    NOT NULL,
    ShipmentStatus    VARCHAR(20),
    WarehouseCity     VARCHAR(50),
    TrackingNumber    VARCHAR(20),
    DispatchDate      TIMESTAMPTZ,
    ExpectedArrival   TIMESTAMPTZ,
    ActualArrival     TIMESTAMPTZ,
    WeightKg          DECIMAL(6,2),
    ShippingCostINR   DECIMAL(10,2),
    updated_at        TIMESTAMPTZ    DEFAULT NOW() NOT NULL
);

-- Publication for Lakeflow Connect (required even for initial load)
CREATE PUBLICATION shipments_publication FOR TABLE public.shipments;

-- Auto-update trigger for CDC cursor column
CREATE OR REPLACE FUNCTION update_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER shipments_updated_at
    BEFORE UPDATE ON public.shipments
    FOR EACH ROW EXECUTE FUNCTION update_updated_at();

